(function () {
  var FRAME_MS = 30; // orijinal GIF ile ayni hiz
  var el = document.getElementById("xrdd-ascii");
  if (!el) return;

  var COLS = FRAMES[0].indexOf("\n");

  // Harf genisligini olc: hucre orani 1:2 kalsin, logo sayfa genisligine otursun
  function fit() {
    var cs = getComputedStyle(el);
    var probe = document.createElement("span");
    probe.style.cssText = "position:absolute;visibility:hidden;white-space:pre;font-size:100px;font-family:" + cs.fontFamily;
    probe.textContent = new Array(101).join("X");
    document.body.appendChild(probe);
    var adv = probe.getBoundingClientRect().width / 100 / 100; // em cinsinden harf genisligi
    document.body.removeChild(probe);
    var host = el.parentElement ? el.parentElement.clientWidth : window.innerWidth;
    var w = Math.min((host || window.innerWidth) * 0.94, 1100);
    var fs = w / (COLS * adv);
    el.style.fontSize = fs + "px";
    el.style.lineHeight = (2 * adv * fs) + "px";
  }
  fit();
  window.addEventListener("resize", fit);

  var still = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  el.textContent = FRAMES[0];
  if (still) return; // hareketi kapatan kullanicilara sabit kare

  var i = 0, last = performance.now(), acc = 0;
  function tick(now) {
    acc += now - last;
    last = now;
    if (acc >= FRAME_MS) {
      var step = Math.floor(acc / FRAME_MS);
      acc -= step * FRAME_MS;
      i = (i + step) % FRAMES.length;
      el.textContent = FRAMES[i];
    }
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
})();
